import{_ as n,c as i,o as t,ah as r}from"./chunks/framework.dGCgOE9J.js";const a="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_storage_preferences.jpg",d="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_file_type_categories.jpg",s="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_feature_files.jpg",o="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_move_files.jpg",k=JSON.parse('{"title":"23. Dateien und Anhänge verwalten","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-b-betrieb-admin-qgis/23-dateien-und-anhaenge.md","filePath":"manual/teil-b-betrieb-admin-qgis/23-dateien-und-anhaenge.md"}'),h={name:"manual/teil-b-betrieb-admin-qgis/23-dateien-und-anhaenge.md"};function l(u,e,c,g,b,m){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="_23-dateien-und-anhange-verwalten" tabindex="-1">23. Dateien und Anhänge verwalten <a class="header-anchor" href="#_23-dateien-und-anhange-verwalten" aria-label="Permalink to &quot;23. Dateien und Anhänge verwalten&quot;">​</a></h1><p>Die Dateien, die Nutzende im Reiter „Anhänge“ hochladen, legt Qonnectra auf dem Server in einer festen Ordnerstruktur ab, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/03-wiederkehrende-bedienelemente.html#_3-7-anhange-hochladen-ansehen-und-loschen">Anhänge hochladen, ansehen und löschen</a>. Dieses Kapitel beschreibt, wie diese Struktur entsteht, wie Sie sie anpassen und wie Sie aufräumen, wenn Anhänge ihr Objekt verloren haben.</p><p>Zu jeder Datei gibt es zwei Dinge: die Datei selbst im Ablageordner und einen Eintrag unter „Api“ → „Feature-Dateien“, der sie mit ihrem Objekt verbindet. Der Reiter „Anhänge“ zeigt nur Dateien, zu denen es diesen Eintrag gibt.</p><h2 id="_23-1-ablagestruktur-der-anhange" tabindex="-1">23.1 Ablagestruktur der Anhänge <a class="header-anchor" href="#_23-1-ablagestruktur-der-anhange" aria-label="Permalink to &quot;23.1 Ablagestruktur der Anhänge&quot;">​</a></h2><p>Eine hochgeladene Datei landet unter diesem Pfad:</p><p><code>Projekt/Objektordner/Objektkennung/Kategorieordner/Dateiname</code></p><ul><li><strong>Projekt</strong> – der Name des Projekts, zu dem das Objekt gehört.</li><li><strong>Objektordner</strong> – je Objektart ein Ordner, etwa <code>trenches</code> für Trassen oder <code>nodes</code> für Netzknoten.</li><li><strong>Objektkennung</strong> – die Trassen-ID, der Name eines Rohrs, Kabels, Netzknotens oder Gebiets, bei Adressen die Anschrift.</li><li><strong>Kategorieordner</strong> – ergibt sich aus der Dateiendung, siehe Abschnitt <a href="#_23-2-dateitypkategorien">Dateitypkategorien</a>.</li></ul><p>Die Anhänge einer Wohneinheit liegen im Ordner ihrer Adresse.</p><p>Welche Ordnernamen gelten, legen die „Speicherpräferenzen“ fest. Es gibt genau einen Eintrag; sein Feld „Folder structure“ ordnet jeder Objektart und jeder Kategorie einen Ordner zu. Für Kabel enthält der mitgelieferte Eintrag keine Zuordnung; ihre Anhänge liegen deshalb ohne Kategorieordner direkt im Ordner des Kabels unter <code>cables</code>.</p><p><img src="'+a+'" alt="Screenshot der Speicherpräferenzen mit der Zuordnung von Objektarten und Kategorien zu Ordnern im Feld „Folder structure“ in der Mitte" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Eine geänderte Ordnerstruktur gilt nur für Dateien, die danach hochgeladen werden. Vorhandene Dateien bleiben, wo sie sind, und ihre Einträge verweisen weiter dorthin. Wer die Struktur ändert, hat danach zwei Ordnungen nebeneinander.</p></div><p>Benennen Sie in der Weboberfläche oder im Administrationsbereich ein Rohr, ein Kabel, einen Netzknoten, eine Adresse oder eine Wohneinheit um, oder bekommt eine Trasse eine neue ID, verschiebt Qonnectra den Ordner mit. Ein Umbenennen in QGIS bewegt nichts, und auch ein umbenanntes Gebiet behält seinen Ordner; die Anhänge bleiben trotzdem erreichbar, nur der Ordnername passt nicht mehr.</p><h2 id="_23-2-dateitypkategorien" tabindex="-1">23.2 Dateitypkategorien <a class="header-anchor" href="#_23-2-dateitypkategorien" aria-label="Permalink to &quot;23.2 Dateitypkategorien&quot;">​</a></h2><p>Die <strong>Dateitypkategorien</strong> ordnen jeder Dateiendung eine Kategorie zu, etwa <code>jpg</code> den Fotos oder <code>pdf</code> den Dokumenten. Sie stehen unter „Dateitypkategorien“, eine Zeile je Endung in der Form „jpg → photos“; die „Beschreibung“ zeigt erst das Formular einer Zeile.</p><p><img src="'+d+'" alt="Screenshot der Liste der Dateitypkategorien mit Endung und Kategorie je Zeile im Inhaltsbereich" data-zoomable="true"></p><p>Mitgeliefert sind die Kategorien <code>photos</code>, <code>documents</code>, <code>cad</code>, <code>data</code>, <code>archives</code> und <code>videos</code>. Eine Endung, die in der Liste fehlt, gilt als Dokument. Eine neue Kategorie braucht zusätzlich einen Ordner in den Speicherpräferenzen; sonst landen ihre Dateien direkt im Ordner des Objekts.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Liste beschränkt nicht, was hochgeladen werden darf. Sie entscheidet nur über den Ordner. Jede Dateiart wird angenommen.</p></div><h2 id="_23-3-großen-und-formatgrenzen" tabindex="-1">23.3 Größen- und Formatgrenzen <a class="header-anchor" href="#_23-3-großen-und-formatgrenzen" aria-label="Permalink to &quot;23.3 Größen- und Formatgrenzen&quot;">​</a></h2><p>Für die Größe einer Datei gelten zwei Grenzen, je nach Weg:</p><table tabindex="0"><thead><tr><th>Weg</th><th>Grenze</th></tr></thead><tbody><tr><td>Reiter „Anhänge“ der Weboberfläche</td><td>50 MB je Datei</td></tr><tr><td>Administrationsbereich und Schnittstelle</td><td>100 MB je Anfrage</td></tr></tbody></table><p>Größere Dateien – Videos von Befahrungen, Punktwolken, umfangreiche CAD-Pläne – nimmt Qonnectra nicht als Anhang an. Legen Sie sie an anderer Stelle ab und verweisen Sie in der Beschreibung eines Anhangs darauf.</p><p>Eine zweite Datei mit demselben Namen am selben Objekt überschreibt die erste, siehe den Hinweis in Abschnitt <a href="./../teil-a-anwenderhandbuch/03-wiederkehrende-bedienelemente.html#_3-7-anhange-hochladen-ansehen-und-loschen">Anhänge hochladen, ansehen und löschen</a>.</p><h2 id="_23-4-zugriff-auf-die-medien-uber-webdav" tabindex="-1">23.4 Zugriff auf die Medien über WebDAV <a class="header-anchor" href="#_23-4-zugriff-auf-die-medien-uber-webdav" aria-label="Permalink to &quot;23.4 Zugriff auf die Medien über WebDAV&quot;">​</a></h2><p>Der Ablageordner ist zusätzlich über <strong>WebDAV</strong> erreichbar, unter einer eigenen Adresse, die mit <code>files.</code> beginnt, etwa <code>https://files.ihre-domain.de</code>. Angemeldet wird mit Benutzername und Passwort aus Qonnectra.</p><p>In der mitgelieferten Konfiguration ist der Zugang schreibgeschützt: Sie können Dateien ansehen und herunterladen, aber nicht ablegen, ändern oder löschen. Er eignet sich, um die Anhänge eines Projekts gesammelt zu kopieren, etwa für eine Übergabe.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>WebDAV kennt keine Rollen und keine Projekte. Jedes aktive Konto liest dort alle Anhänge aller Projekte – auch ein Konto der Rolle „Viewer“ und auch ein Konto, das in der Weboberfläche keine einzige Objektart sehen darf. Geben Sie die Adresse nur weiter, wo der Zugang gebraucht wird; sperren lässt er sich nur auf Ebene des Servers, siehe Kapitel <a href="./28-betrieb-der-instanz.html">Betrieb der Instanz</a>.</p></div><h2 id="_23-5-verwaiste-dateien-finden-verschieben-und-loschen" tabindex="-1">23.5 Verwaiste Dateien finden, verschieben und löschen <a class="header-anchor" href="#_23-5-verwaiste-dateien-finden-verschieben-und-loschen" aria-label="Permalink to &quot;23.5 Verwaiste Dateien finden, verschieben und löschen&quot;">​</a></h2><p>Wird ein Objekt gelöscht – in der Weboberfläche, im Administrationsbereich oder in QGIS –, bleiben seine Anhänge zurück: die Dateien im Ablageordner und ihre Einträge unter „Feature-Dateien“. Solche <strong>verwaisten Dateien</strong> zeigt die Liste der Feature-Dateien, wenn Sie rechts unter „Verwaist-Status“ den Filter „Nur verwaiste Dateien“ wählen.</p><p><img src="'+s+'" alt="Screenshot der Feature-Dateien, gefiltert auf verwaiste Dateien, mit Hervorhebung des Filters und der Aktionen" data-zoomable="true"></p><p>Für verwaiste Dateien gibt es zwei Aktionen:</p><ul><li>„Ausgewählte Dateien zu einem anderen Feature verschieben“ – hängt die Dateien an ein anderes Objekt. Das ist der Weg, wenn ein Objekt gelöscht und neu angelegt wurde, etwa ein Netzknoten nach einer Korrektur in QGIS.</li><li>„Ausgewählte verwaiste Dateien und ihre Daten löschen“ – löscht Einträge und Dateien. Dateien, deren Objekt noch existiert, überspringt die Aktion.</li></ul><p>Zum Verschieben:</p><ol><li>Haken Sie die Dateien an, wählen Sie die Aktion „Ausgewählte Dateien zu einem anderen Feature verschieben“ und klicken Sie auf „Ausführen“.</li><li>Wählen Sie im folgenden Formular unter „Feature-Typ“ die Objektart und tragen Sie unter „Feature-UUID“ die UUID des neuen Objekts ein. Sie steht im Formular des Objekts im Administrationsbereich im Feld „Uuid“.</li><li>Klicken Sie auf „Dateien verschieben“.</li></ol><p><img src="'+o+'" alt="Screenshot des Formulars zum Verschieben verwaister Dateien mit der Liste der ausgewählten Dateien oben und dem Ziel darunter" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die gewöhnliche Aktion „Ausgewählte … löschen“ fehlt in dieser Liste mit Absicht: Sie würde nur die Einträge entfernen und die Dateien als unauffindbaren Rest im Ablageordner lassen. Die Schaltfläche „Löschen“ im Formular einer einzelnen Feature-Datei gibt es dagegen weiterhin, und sie tut genau das: Der Eintrag verschwindet, die Datei bleibt zurück. Löschen Sie Anhänge deshalb immer über die Aktion für verwaiste Dateien oder im Reiter „Anhänge“.</p></div>',35)])])}const f=n(h,[["render",l]]);export{k as __pageData,f as default};
